import{_ as o,o as t,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Sequence Flow — View User Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-1-view-user-profile/sequence-flow.md","filePath":"feature/profile/3-3-1-view-user-profile/sequence-flow.md"}'),s={name:"feature/profile/3-3-1-view-user-profile/sequence-flow.md"};function d(l,e,a,c,n,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="sequence-flow-—-view-user-profile" tabindex="-1">Sequence Flow — View User Profile <a class="header-anchor" href="#sequence-flow-—-view-user-profile" aria-label="Permalink to &quot;Sequence Flow — View User Profile&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.3.1). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those). &gt; &gt; Updated: 2026-09-25. Matches the current implementation.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — the signed-in user.</li><li><strong>Client</strong> — the Profile screen at <code>/profile</code> (view mode).</li><li><strong>System</strong> — <code>UserController</code> / <code>UserServiceImpl</code>.</li><li><strong>Database</strong> — PostgreSQL (<code>users</code>, <code>user_system_roles</code>, <code>workspace_members</code>).</li></ul><hr><h2 id="flow-a-—-view-the-signed-in-user-s-own-profile" tabindex="-1">Flow A — View the signed-in user&#39;s own profile <a class="header-anchor" href="#flow-a-—-view-the-signed-in-user-s-own-profile" aria-label="Permalink to &quot;Flow A — View the signed-in user&#39;s own profile&quot;">​</a></h2><ol><li>User → Client: opens <code>/profile</code>.</li><li>Client → System: <code>GET /api/v1/users/me</code>, carrying the access token and no user identifier.</li><li>System (<code>UserServiceImpl.getUserProfile</code>): resolves the caller&#39;s identity from the authenticated token.</li><li>System → Database: <code>UserRepository.findById(currentUser.getId())</code> — not found → <code>404 USER_NOT_FOUND</code> (theoretical: with a valid token the user always exists).</li><li>System → Database: <code>UserSystemRoleRepository.findByUserId(...)</code>; when no role record exists, the role defaults to <code>USER</code>.</li><li>System → Database: when <code>currentUser.getWorkspaceId()</code> is null, falls back to <code>WorkspaceMemberRepository.findFirstByUserIdAndIsActiveTrue(...)</code>.</li><li>System: parses the user&#39;s <code>preferences</code> JSON column to derive <code>timezone</code> and <code>notificationPreferences</code>; parses the <code>portfolioUrls</code> JSON column into a list of strings (blank/unparsable → empty list, never an error).</li><li>System → Client: returns the complete profile field set — <code>userId</code>, <code>email</code>, <code>fullName</code>, <code>avatarUrl</code>, <code>phone</code>, <code>role</code>, <code>workspaceId</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>, <code>timezone</code>, <code>notificationPreferences</code>, <code>createdAt</code>.</li><li>Client: renders the fields in the read-only view — job title, working language, timezone, bio, and portfolio links included; no direct editing here, the Edit button switches the same page into edit mode (FR 3.3.2). <ul><li><code>avatarUrl</code> empty → a default initials avatar is shown.</li><li>Any optional field empty (<code>phone</code>, <code>professionalTitle</code>, <code>bio</code>, <code>portfolioUrls</code>, <code>workingLanguage</code>) → an empty-state placeholder is shown, not an error.</li></ul></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>View profile</td><td>Missing, expired, or invalid token (blocked before the operation is reached)</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>View profile</td><td>The user record no longer exists (theoretical: valid token held for a deleted user)</td><td>404</td><td><code>USER_NOT_FOUND</code></td></tr></tbody></table>',10)])])}const u=o(s,[["render",d]]);export{f as __pageData,u as default};
